        if event_reopen:
            options.append(reopen_event)
        if hierarchical_p0:
            options.insert(0, p0)
        if probe_id is not None:
            options.append(obj({"action": const("probe"), "probe_id": {"type": "string", "const": probe_id}}, ["action", "probe_id"]))
        schema = {"oneOf": options}
    else:
