    return {
        "type": "json_schema",
        "json_schema": {
            "name": (
                f"experiment_002_{stage}_action"
                if read_mode == "actor_selected_count"
                else f"experiment_013_{stage}_receipt_action"
                if result_reopen
                else f"experiment_010_{stage}_maximal_read_action"
            ),
            "strict": True,
            "schema": schema,
        },
    }
